from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]/'dist/assets'
def save(name,bg,art):
 ROOT.joinpath(name+'.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="800" height="480" viewBox="0 0 800 480"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="{bg[0]}"/><stop offset="1" stop-color="{bg[1]}"/></linearGradient><radialGradient id="light"><stop stop-color="#fff" stop-opacity=".17"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#f1f4ef"/><stop offset="1" stop-color="#738b96"/></linearGradient></defs><rect width="800" height="480" fill="url(#bg)"/><circle cx="610" cy="170" r="300" fill="url(#light)"/>{art}</svg>')
def wheel(x,y,r=37):return f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*.8}" fill="#101c20"/><ellipse cx="{x}" cy="{y}" rx="{r*.55}" ry="{r*.46}" fill="#c5d0ca"/><ellipse cx="{x}" cy="{y}" rx="{r*.3}" ry="{r*.26}" fill="#51676b"/>'
buildings=''.join(f'<path d="M{x} 0h{w}v{h}h-{w}z" fill="#243f40"/><path d="M{x+12} 20h8v{h-32}h-8z" fill="#6da2a0" opacity=".3"/>' for x,w,h in [(5,55,180),(84,72,125),(190,47,155),(614,64,152),(711,80,207)])
road='<path d="M0 480V315L455 160L800 185V480" fill="#2d4140"/><path d="M-50 450L465 199L850 229" fill="none" stroke="#c2d4a0" stroke-width="8"/><path d="M220 500L520 225L830 253" fill="none" stroke="#a5bcb4" stroke-width="4" stroke-dasharray="32 30"/>'
kart=wheel(371,346)+wheel(568,379)+wheel(523,286,27)+wheel(324,283,25)+'<path d="M301 298L422 253L591 327L514 369Z" fill="#d6f585"/><path d="M301 298L514 369V395L301 323Z" fill="#78aa49"/><path d="M514 369L591 327V351L514 395Z" fill="#b2d961"/><path d="M367 286L420 267L514 305L465 327Z" fill="#19362c"/><path d="M401 287L438 300L463 286L426 274Z" fill="#d6e5d8"/><path d="M389 258L435 241L464 257L420 275Z" fill="#253f35"/><path d="M389 258V281L419 295L420 275Z" fill="#173128"/><path d="M365 228L403 211L498 251L458 269Z" fill="#d7f589"/><path d="M365 228V239L458 280V269Z" fill="#86b649"/><path d="M396 275V244M464 302V276" stroke="#6c8b70" stroke-width="7"/><ellipse cx="449" cy="236" rx="25" ry="24" fill="#e4ecde"/><path d="M434 218L461 226L458 242L432 234Z" fill="#467777"/><path d="M588 350L679 374M590 367L717 397M594 385L667 411" stroke="#caff79" stroke-width="5" opacity=".6"/>'
save('turbo',('#142f2b','#497060'),buildings+road+kart+'<path d="M76 258l32-18M93 277l47-23M128 296l47-23" stroke="#c7ed98" stroke-width="3" opacity=".5"/>')
# Original blocky arena characters and an energy weapon.
city=''.join(f'<path d="M{x} {y}l80-38 65 33v{h}l-80 38-65-33z" fill="{c}"/><path d="M{x} {y}l65 33 80-38" fill="none" stroke="#987eef" stroke-width="3"/>' for x,y,h,c in [(30,130,170,'#342f59'),(605,97,215,'#322c51'),(410,200,90,'#41316a')])
player='<path d="M230 243l80-31 82 36-74 38z" fill="#a39aff"/><path d="M230 243v94l88 41v-92z" fill="#7565c3"/><path d="M318 286l74-38v95l-74 35z" fill="#9687e7"/><path d="M245 335v89l33 15v-84M334 366v64l34-15v-74" stroke="#273044" stroke-width="37"/><path d="M270 166l53-25 51 25v61l-52 26-52-25z" fill="#ddd6f6"/><path d="M272 195l49 23 49-24v25l-49 25-49-24z" fill="#282a49"/><path d="M385 271l67-29 34 18-65 31z" fill="#ccd7e9"/><path d="M421 291v30l65-29v-32z" fill="#707d99"/><path d="M486 260l55-23 13 10-68 29" fill="#97e8ee"/><path d="M546 242l91-38" stroke="#9ffff0" stroke-width="7"/><path d="M225 284l-29 9v68l34 13" fill="#6253a5"/>'
save('neon',('#211b40','#543380'),city+'<path d="M0 410L800 286V480H0" fill="#211e37"/><path d="M0 447l800-116M199 480l600-178" stroke="#926fe7" stroke-width="2"/>'+player+'<circle cx="649" cy="196" r="9" fill="#a2fff0"/><path d="M644 175l10-12M662 193h18M646 214l4 15" stroke="#a2fff0" stroke-width="3"/>')
platforms=''
for x,y,w,h,top,side in [(37,332,175,48,'#d6b486','#9b714d'),(278,274,160,42,'#b2b1ba','#5f6477'),(470,200,144,38,'#bebbc4','#626274'),(609,117,126,35,'#9fd7b5','#579d84')]:
 platforms+=f'<path d="M{x} {y}l{w*.6}-{h} {w*.6} {h*.4} -{w*.6} {h}z" fill="{top}"/><path d="M{x} {y}v28l{w*.6} {h*.4}v-28z" fill="{side}"/><path d="M{x+w*.6} {y+h*.4}l{w*.6}-{h}v28l-{w*.6} {h}z" fill="#424755"/>'
save('lava',('#401d24','#a74936'),'<path d="M0 360L800 268V480H0Z" fill="#f27738"/><path d="M0 430l128-50 87 70 143-55 94 36 151-66 197 55" fill="none" stroke="#ffc477" stroke-width="12"/><path d="M0 449l128-50 87 70 143-55 94 36 151-66 197 55" fill="none" stroke="#e14427" stroke-width="22"/>'+platforms+'<path d="M705 106V33" stroke="#d5f6d0" stroke-width="5"/><path d="M709 32l50 5-21 28-29-4z" fill="#82efa5"/><path d="M426 160l27-9 28 16-28 12z" fill="#f1e7d4"/><path d="M426 160v38l27 15 0-34z" fill="#ddba9d"/><path d="M453 179l28-12v37l-28 14" fill="#dc8668"/><path d="M437 200l-15 45M463 212l13 29" stroke="#2b303c" stroke-width="14"/><path d="M429 180l-30 8M477 181l21-23" stroke="#eab28e" stroke-width="12"/><path d="M157 159l18-15M226 213l20-15M571 66l11-17" stroke="#ffad73" stroke-width="4"/>')
colors=['#f17d88','#72b4f4','#f4d679','#7dd8b5','#b196ed','#efa876'];tiles=''
for r in range(5):
 for c in range(6):
  x=385+(c-r)*53;y=140+(c+r)*28;col=colors[(r*3+c)%6]
  tiles+=f'<path d="M{x} {y}l51 27-51 27-51-27z" fill="{col}" stroke="#d4e7df" stroke-width="2"/>'
characters=''
for x,y,col in [(391,184,'#ffd574'),(229,269,'#7cd4cf'),(554,274,'#b6a2f2')]:
 characters+=f'<path d="M{x-18} {y}l20-8 20 10v35l-20 8-20-10z" fill="{col}"/><ellipse cx="{x+2}" cy="{y-13}" rx="18" ry="17" fill="#f4eadb"/><path d="M{x-7} {y+31}v22M{x+17} {y+32}v22" stroke="#2b3b4f" stroke-width="12"/>'
save('color',('#16434c','#458e91'),'<path d="M70 398l334-185 326 173-350 93z" fill="#13333d"/>'+tiles+characters+'<rect x="288" y="23" width="204" height="59" rx="12" fill="#f3ebd9"/><text x="390" y="64" fill="#37595e" font-family="Arial" font-size="32" font-weight="bold" text-anchor="middle">◆ GREEN</text><path d="M169 114l18 12-18 13-19-13zM655 124l18 12-18 13-19-13z" fill="#72e2b9" opacity=".7"/>')
field='<path d="M0 355L460 97 800 269V480H0Z" fill="#386c47"/><path d="M137 347L429 186 650 304 365 462Z" fill="#c79c6f"/><path d="M221 331l199-110 151 81-200 112z" fill="#68a369"/><path d="M136 346L458 112M365 460L741 273" stroke="#f2e6c9" stroke-width="4"/><path d="M422 202l11-6 13 7-12 7zM568 301l12-7 13 8-13 7zM222 331l12-6 12 7-12 7z" fill="#fff4e0"/>'
ball='<circle cx="570" cy="178" r="100" fill="#f3ebd6"/><path d="M513 100q111 75 3 159M626 100q-110 75-3 159" fill="none" stroke="#cb6b59" stroke-width="5"/>'
for x,y,a in [(527,124,-.5),(543,146,-.3),(548,170,0),(546,194,.3),(531,217,.6),(611,124,.5),(595,146,.3),(590,170,0),(592,194,-.3),(607,217,-.6)]:ball+=f'<path d="M{x-7} {y-4}l14 8" stroke="#cb6b59" stroke-width="3" transform="rotate({a*50} {x} {y})"/>'
save('baseball',('#253d35','#6b8860'),field+'<path d="M80 340L253 171" stroke="#c99864" stroke-width="39" stroke-linecap="round"/><path d="M53 367l59-57" stroke="#294344" stroke-width="23" stroke-linecap="round"/>'+ball+'<path d="M439 100l-36-22M437 79l-27-34M664 252l38 35M674 231l49 21" stroke="#f0c96c" stroke-width="5"/>')
print('Created five original SVG game posters.')
